import { listTools, callTool } from './server.mjs';
const assert = (cond, msg) => { if (!cond) { console.error('FAIL:', msg); process.exitCode = 1; } };

// unknown tool
try { await callTool('bogus', {}); assert(false, 'unknown tool should throw'); }
catch (e) { assert(/Unknown tool/.test(e.message), 'unknown tool msg'); }

// missing fields
for (const f of ['a','b','operation']) {
  const args = { a:1, b:2, operation:'add' }; delete args[f];
  try { await callTool('calculate', args); assert(false, 'missing '+f+' should throw'); }
  catch (e) { assert(e.message.includes(f), 'missing '+f+' msg: '+e.message); }
}

// extra field
try { await callTool('calculate', { a:1, b:2, operation:'add', extra:9 }); assert(false, 'extra field should throw'); }
catch (e) { assert(/Unexpected field/.test(e.message), 'extra field msg: '+e.message); }

// unsupported operation
try { await callTool('calculate', { a:1, b:2, operation:'pow' }); assert(false, 'unsupported op should throw'); }
catch (e) { assert(/Unsupported operation/.test(e.message), 'unsupported op msg: '+e.message); }

// division by zero
try { await callTool('calculate', { a:1, b:0, operation:'divide' }); assert(false, 'div by zero should throw'); }
catch (e) { assert(/Division by zero/.test(e.message), 'div by zero msg: '+e.message); }

// valid ops
assert((await callTool('calculate',{a:10,b:3,operation:'subtract'})).content[0].text === '7', 'subtract');
assert((await callTool('calculate',{a:4,b:5,operation:'multiply'})).content[0].text === '20', 'multiply');
assert((await callTool('calculate',{a:8,b:2,operation:'divide'})).content[0].text === '4', 'divide');

// non-numeric
try { await callTool('calculate', { a:'x', b:2, operation:'add' }); assert(false, 'non-number a should throw'); }
catch (e) { assert(/must be a finite number/.test(e.message), 'non-number a msg: '+e.message); }

// NaN / Infinity rejected
try { await callTool('calculate', { a:NaN, b:2, operation:'add' }); assert(false, 'NaN should throw'); }
catch (e) { assert(/must be a finite number/.test(e.message), 'NaN msg'); }

// schema check
const [t] = await listTools();
assert(t.inputSchema.additionalProperties === false, 'additionalProperties false');
assert.deepEqual; // no-op
console.log('All sanity checks passed.');
"
